```tsx
import type { ReactElement } from "react";
import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps): ReactElement {
  return (
    <div className="alert-banner" role="alert">
      <p className="alert-banner__message">{message}</p>
      <button type="button" className="alert-banner__retry" onClick={onRetry}>
        Retry
      </button>
    </div>
  );
}
```

```css
.alert-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--cresyl);
  border-left-width: 4px;
  border-radius: 10px;
  background: var(--cresyl-wash);
  color: var(--ink);
  font-size: clamp(0.9rem, 0.8rem + 0.4vw, 1.05rem);
}

.alert-banner__message {
  margin: 0;
  flex: 1 1 16rem;
}

.alert-banner__retry {
  font: inherit;
  font-weight: 600;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.35rem 0.9rem;
  cursor: pointer;
  transition: background-color 150ms ease;
}

.alert-banner__retry:hover {
  background: var(--myelin-wash);
}

:root[data-motion="reduce"] .alert-banner__retry {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .alert-banner__retry {
    transition: none;
  }
}
```

